#!/usr/bin/env python3
"""Generate the self-contained English developer handover from actual resources."""
from pathlib import Path
import json, html
R=Path(__file__).resolve().parents[2]
c=json.loads((R/'campaign/content/campaign.json').read_text())
m=json.loads((R/'campaign/assets/music/manifest.json').read_text())
prose=[p for s in c['scenes'] for p in s['paragraphs']]
for e in c['endings']:
    prose.extend(e['paragraphs'])
    for ep in e.get('epilogues',[]):prose.extend(ep['paragraphs'])
prose.extend(s['survey']['text'] for s in c['systems'] if 'survey' in s)
words=sum(len(p.split()) for p in set(prose))
eps={json.dumps(ep,sort_keys=True) for e in c['endings'] for ep in e.get('epilogues',[])}
choices=sum(len(s['choices']) for s in c['scenes'])
surveys=sum('survey' in s for s in c['systems'])
characters=''.join(f'<article><small>{html.escape(x["species"])}</small><h3>{html.escape(x["name"])}</h3><p>{html.escape(x["role"])}</p></article>' for x in c['characters'])
tracks=''.join(f'<tr><td>{html.escape(t["title"])}</td><td>{t["bpm"]}</td><td>{t["duration"]:.0f}s</td><td><code>{t["id"]}</code></td></tr>' for t in m['tracks'])
report={}
p=R/'test-results/afterlight-browser/results.json'
if p.exists():report=json.loads(p.read_text())
routes=''.join(f'<tr><td>{html.escape(e["ending"])}</td><td>{e["actions"]}</td><td>{e["day"]}</td><td>{e["systems"]}</td></tr>' for e in report.get('routes',[]))
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Afterlight Accord — developer handover</title><style>
:root{{--bg:#08151e;--panel:#102631;--ink:#e8e5d6;--muted:#a9bec6;--gold:#e5bc79;--line:#31505c}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,sans-serif}}a{{color:#9de0d7}}.wrap{{max-width:1120px;margin:auto;padding:0 36px}}header{{padding:72px 0 56px;background:radial-gradient(ellipse at 90% 0,#425959,transparent 55%),linear-gradient(125deg,#132a37,#07121a);border-bottom:1px solid var(--line)}}.kicker,small{{display:block;color:var(--gold);letter-spacing:.14em;text-transform:uppercase;font-size:11px}}h1,h2,h3{{font-family:Georgia,serif;font-weight:400;line-height:1.16}}h1{{font-size:clamp(42px,7vw,80px);letter-spacing:-.045em;margin:20px 0}}h2{{font-size:34px;margin:0 0 22px}}h3{{font-size:22px;margin:8px 0 14px}}.dek{{max-width:740px;font-size:20px;color:#c6d6da}}.meta{{display:flex;gap:14px;flex-wrap:wrap;margin-top:32px}}.pill{{border:1px solid #52717b;border-radius:99px;padding:6px 14px;font-size:12px}}nav{{display:flex;flex-wrap:wrap;gap:12px 22px;padding:22px 0;border-bottom:1px solid var(--line)}}nav a{{margin-right:0;white-space:nowrap;font-size:13px}}section{{padding:48px 0;border-bottom:1px solid var(--line)}}p{{margin:0 0 18px}}.muted{{color:var(--muted)}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}}.grid article{{padding:22px;background:var(--panel);border-top:2px solid var(--gold)}}.grid p{{color:var(--muted);font-size:14px;margin:0}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:28px 0}}.stat{{border-left:2px solid var(--gold);padding-left:16px;font-size:13px;color:var(--muted)}}.stat strong{{display:block;font:34px Georgia,serif;color:var(--ink)}}.note{{padding:20px 24px;border-left:3px solid var(--gold);background:var(--panel);margin:25px 0}}.split>* , .grid>*{{min-width:0}}.split{{display:grid;grid-template-columns:1fr 1fr;gap:32px}}code{{font-size:13px;overflow-wrap:anywhere}}pre{{padding:20px;background:#040d14;border:1px solid var(--line);overflow:auto;line-height:1.55}}table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:12px 10px}}th{{color:var(--gold);font-weight:500}}.table{{overflow-x:auto}}li{{margin-bottom:9px}}details{{padding:20px;background:var(--panel);margin:22px 0}}summary{{cursor:pointer;color:var(--gold);font-weight:600}}details p{{margin-top:18px}}footer{{padding:36px 0 70px;color:var(--muted);font-size:13px}}@media(max-width:700px){{.wrap{{padding:0 20px}}header{{padding:40px 0}}.grid,.split{{grid-template-columns:1fr}}.stats{{grid-template-columns:1fr 1fr}}section{{padding:32px 0}}h2{{font-size:29px}}}}@media print{{body{{background:white;color:#14212a;font-size:11px}}header{{background:white;padding:20px 0}}.wrap{{max-width:none}}.grid article,.note,details{{background:#f2f5f4}}.muted,.grid p,small,.kicker{{color:#455960}}a{{color:#185761}}section{{break-inside:avoid;padding:20px 0}}pre{{background:#edf1f2;color:#14212a}}nav{{display:none}}h1{{font-size:44px}}}}
</style></head><body><header><div class="wrap"><span class="kicker">UQM · Original fan continuation · Developer handover</span><h1>The Afterlight Accord</h1><p class="dek">A complete new branching expedition in the Far Reach, with authored consequences, original illustrations and music, physical surface exploration, and genuine Rust UQM combat.</p><div class="meta"><span class="pill">Branch: codex/uqm-new-campaign</span><span class="pill">21 October 2026</span><span class="pill">English campaign</span></div></div></header><div class="wrap"><nav><a href="#play">Play</a><a href="#scope">Scope</a><a href="#architecture">Architecture</a><a href="#validation">Validation</a><a href="#resources">Resources</a><a href="#handoff">Handoff</a></nav>
<section id="play"><small>01 / Start here</small><h2>A ship with one extra chair.</h2><p>Seven years after the Sa-Matra’s defeat, the Wayfarer surveys settlements beyond the old Hierarchy frontier. An abandoned planetary shield requests a passenger berth. The caller is new, alive, and difficult to fit into a reconstruction system that already knows how every request should be answered.</p><p>Original victories remain meaningful. The new story grows from the unfinished work of liberation, with humor, material constraints and people whose interests do not neatly agree.</p><div class="split"><div><h3>Local preview</h3><pre>npm run build:afterlight\nnpm run start:afterlight</pre><p><a href="http://127.0.0.1:10002/">Open the local game →</a></p><p class="muted">Use the pinned toolchains described in the repository README. Once native combat is built, <code>bash scripts/build-afterlight.sh --ui-only</code> repackages narrative and interface changes quickly.</p></div><div><h3>What the player gets</h3><p>Star chart, travel and resupply, readable transmissions, portraits, musical themes, evidence and quest journal, complete conversation log, automatic saves with backup recovery, import/export, surface expeditions, space battles and three fully authored endings.</p><p class="muted">Reading is untimed. Travel and certain decisions advance days. Resource exhaustion, retreat and defeat have recovery paths. Known open signals are listed in the journal.</p></div></div></section>
<section id="scope"><small>02 / Delivered scope</small><h2>Four acts. Three futures.</h2><div class="stats"><div class="stat"><strong>{len(c['scenes'])}</strong>authored conversation scenes</div><div class="stat"><strong>{words:,}</strong>unique narrative words</div><div class="stat"><strong>{len(c['systems'])}</strong>charted systems</div><div class="stat"><strong>{len(c['quests'])}</strong>quest threads</div><div class="stat"><strong>{choices}</strong>authored responses</div><div class="stat"><strong>{surveys}</strong>physical survey locations</div><div class="stat"><strong>{len(eps)}</strong>conditional epilogue entries</div><div class="stat"><strong>{sum(t['duration'] for t in m['tracks'])/60:.1f} min</strong>original instrumental score</div></div><p class="muted">Narrative words count unique scene, ending, epilogue and survey prose. Repeated epilogues attached to several endings are counted once. This is substantially smaller than the original campaign’s approximately 98,143 dialogue words.</p><div class="grid"><article><small>I / A new passenger</small><h3>Listen before deciding.</h3><p>Meet the Wayfarer’s crew, recover the first Afterlight, and discover the cost of sustaining a new life.</p></article><article><small>II / Six independent leads</small><h3>Promises acquire weight.</h3><p>A missing passenger, borrowed heat, public records, restitution, an unfinished synthesis and a refusal reveal different parts of the Reach.</p></article><article><small>III / IV</small><h3>Investigate, build, commit.</h3><p>Test the evidence, assemble real infrastructure and choose a settlement whose costs remain visible in the ending.</p></article></div><details><summary>Plot architecture — major spoilers</summary><p>The reconstruction network creates provisional Afterlight minds to forecast decisions, then discards versions that refuse. Sera authorized predictive assent without understanding the lives being erased. Discovery does not make her previous authority legitimate or her relief work worthless.</p><p>The pluralist accord requires actual clocks, public witnesses, independent capacity and a prepared harbor. The mandate saves people through centralized authority with selectable safeguards. Partition preserves autonomy while reducing the Reach’s shared capacity. Each ending has consequences and conditional personal epilogues. The game does not reduce this to a universal morality score.</p><p>The story bible records the full four-act outline, faction motives, reveal timing, clue routes, canonical boundaries and unresolved mysteries.</p></details><h3>Ten principal characters</h3><div class="grid">{characters}</div></section>
<section id="architecture"><small>03 / Implementation</small><h2>Authored data, deterministic rules, real encounters.</h2><div class="table"><table><tr><th>Layer</th><th>Implementation</th><th>Contract</th></tr><tr><td>Narrative</td><td><code>campaign/content/campaign.json</code></td><td>Scenes, choices, requirements, resources, discoveries, world events and endings. No runtime story generation.</td></tr><tr><td>Campaign state</td><td><code>campaign/src/state.mjs</code></td><td>Immutable atomic actions, strict save validation, one-time rewards, explicit pending encounters and matching receipts.</td></tr><tr><td>Presentation</td><td><code>app.mjs</code>, HTML and CSS</td><td>Responsive illustrated interface, full transcripts, keyboard choices, accessible buttons and larger text.</td></tr><tr><td>Surface</td><td><code>lander.mjs</code>, Canvas</td><td>Seeded terrain, fixed-step acceleration and braking, hazards, battery, ore, three physical scans and a return to the pad.</td></tr><tr><td>Combat</td><td>Original UQM Rust → WebAssembly</td><td>Native hulls, weapons, specials, AI, collision and crew. An isolated iframe reports a real victory, defeat or withdrawal.</td></tr><tr><td>Music</td><td>Local Ogg + Web Audio</td><td>15 original cues with crossfades, user-gesture activation, bounded cache and a music toggle.</td></tr><tr><td>Build</td><td><code>scripts/build-afterlight.sh</code></td><td>Clean portable output, SHA-256 file manifest, no stale build assets. Refuses to replace unrelated output directories.</td></tr></table></div><p class="note">The campaign shell and new surface game are JavaScript. Space combat uses the existing Rust translation and preserves original UQM pixel-art ships and sound effects. This is not a claim that the entire campaign is Rust, that all ships were redrawn, or that the original lander was ported into this new interface.</p><h3>Hosting</h3><p>Serve <code>.tools/afterlight-dist/</code> over HTTPS with <code>Cross-Origin-Opener-Policy: same-origin</code> and <code>Cross-Origin-Embedder-Policy: require-corp</code>. Serve <code>.mjs</code> as JavaScript and <code>.wasm</code> as WebAssembly. The included Rust server already provides the necessary behavior. Localhost is sufficient for local play. No campaign server, AI subscription, telemetry or remote media service is required. For a downloadable release from a clean committed checkout, run <code>bash scripts/package-afterlight-release.sh</code>. The resulting ZIP includes an exact corresponding source archive, revision, file hashes and hosting instructions.</p><p>Use a dedicated path or origin for preview. The existing Original/HD launchers and multiplayer system remain separate. Deployment and a merge to main have not been requested.</p></section>
<section id="validation"><small>04 / Evidence</small><h2>Test what the player actually does.</h2><p>The browser suite played all three final routes from a new expedition using visible controls and compared the complete resulting state with the ordinary-action state model. It did not inject flags, resources or ending states.</p><div class="table"><table><tr><th>Ending</th><th>Ordinary actions</th><th>Ending day</th><th>Visited systems</th></tr>{routes}</table></div><ul><li>Every authored scene has an action-based reachability route. A longer tour can complete all 15 quests.</li><li>Each of the six Act-II leads independently opens Act III. Late, poor and previously stranded expeditions can still finish. The four timed events are one-shot and survive save/load.</li><li>Native production combat was physically won, lost and withdrawn from; sequential encounters and multi-ship enemy fleets were checked. All 25 player hulls were launched with their correct crew.</li><li>Surface physics tests cover 300 seeds, boundaries, fixed-step determinism, damage recovery, salvage conservation and the requirement to return after all three scans.</li><li>Browser audio produced nonzero PCM and the music toggle silenced it. All ten portraits loaded, and all fifteen stereo Ogg files decoded in Chrome.</li><li>Save reload, export, invalid-import preservation and recovery from a corrupt primary save passed. Desktop and 390-pixel layouts were checked for overflow.</li></ul><pre>npm run test:afterlight\nnpm run test:afterlight:browser\nnode campaign/tests/integration-encounters.mjs\nnode campaign/tests/combat-browser.mjs\nnode campaign/tests/lander-browser.mjs\npython3 campaign/tools/verify-audio.py</pre><p class="muted">Tracked evidence: <code>campaign/gameplay-validation.json</code> and <code>campaign/validation-summary.json</code>. Reproducible tests generate screenshots and detailed receipts under <code>test-results/</code>. CI is defined in <code>.github/workflows/afterlight.yml</code>; local success does not imply hosted CI has finished.</p></section>
<section id="resources"><small>05 / Resource inventory</small><h2>Everything needed at runtime is local.</h2><p>Ten original high-resolution character portraits, one cover illustration, fifteen synthesized stereo music files, fifteen editable MIDI scores, score metadata, a reproducible composer, authored narrative content and procedural chart/surface visuals are included. Native UQM ship resources retain their original notices.</p><div class="table"><table><tr><th>Composition</th><th>BPM</th><th>Length</th><th>Resource ID</th></tr>{tracks}</table></div><h3>Provenance and editability</h3><p>The new illustrations were generated from text with OpenAI’s built-in image tool. <code>campaign/assets/art-manifest.json</code> records generation mode, art direction, briefs, dimensions and hashes. The music uses explicitly authored motifs and arrangements rendered by <code>campaign/tools/compose.py</code>; it contains no sampled recordings. The editable scores and generator are delivered alongside the recordings.</p><p>New code and writing are GPL-2.0-or-later. New generated art and synthesized music are CC BY-SA 4.0 to the extent rights are held. Existing UQM code and assets keep their existing terms. See <code>campaign/CREDITS.html</code>. No recorded voice performances are included.</p></section>
<section id="handoff"><small>06 / Continue development</small><h2>A complete campaign, ready for human review.</h2><p>Keep the story schema and state tests together. For any plot edit, validate references and replay affected ending and recovery routes. Native Rust hooks are documented and preserved in <code>campaign/native-hooks.patch</code>; apply them to a staging translation rather than overwriting the working engine.</p><div class="split"><div><h3>Reading order</h3><ol><li><code>campaign/README.md</code> — play, build and controls</li><li><code>docs/afterlight-story-bible.md</code> — complete narrative and spoiler notes</li><li><code>campaign/SCHEMA.md</code> — data and save contracts</li><li><code>campaign/NATIVE-COMBAT.md</code> — combat and surface integration</li><li><code>docs/afterlight-original-study-*.md</code> — original-campaign research and limits</li></ol></div><div><h3>Before a public release</h3><p>Invite independent players to complete several routes without a guide. Review pacing, humor, emotional payoffs, music fatigue, difficulty and accessibility. Test Safari and Firefox and longer sessions. Mobile reading and surface controls work; native battles still need a keyboard.</p><p>A test suite establishes functional evidence. It cannot establish that a new story equals or exceeds Star Control II. That judgment belongs to readers and players.</p></div></div><p><a href="https://github.com/vcorem/uqm-3do-web/tree/codex/uqm-new-campaign">Open the campaign branch on GitHub →</a></p></section><footer>Self-contained English handover · The Afterlight Accord project · No external fonts, scripts or assets are required to read this document.</footer></div></body></html>'''
(R/'docs/afterlight-handover.html').write_text(body)
print(f'Handover: {words:,} unique narrative words; {choices} responses; {len(eps)} conditional epilogues.')
